param([string]$MigrationPath="$PSScriptRoot/../../sql/updates/world/2026_10_27_06_lights_wrath_pickup_recovery.sql",[switch]$VerifyLive)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/lights-wrath-pickup-data"
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories $out -Test {
 $migration=Get-Content $MigrationPath -Raw
 $native=Get-Content "$PSScriptRoot/LightsWrathPickupOriginal.json" -Raw|ConvertFrom-Json
 $filters=[ordered]@{gameobject_template='entry IN(248572,248574,244556,251677)';smart_scripts='entryorguid IN(248572,248574,106756) OR(action_type=50 AND action_param1=248574)';conditions='(SourceTypeOrReferenceId=22 AND SourceEntry IN(248572,248574)) OR(SourceTypeOrReferenceId=17 AND SourceEntry IN(208011,218172)) OR(SourceTypeOrReferenceId=4 AND SourceGroup=248572)';spell_script_names='ABS(spell_id) IN(208011,218172)';spell_scene='MiscValue=1244';spell_target_position='id=218172';gameobject='id IN(248572,248574)'}
 $setup='';foreach($t in $filters.Keys){$setup+="CREATE TEMPORARY TABLE saved_$t LIKE $t;INSERT INTO saved_$t SELECT * FROM $t WHERE $($filters[$t]);CREATE TEMPORARY TABLE $t LIKE saved_$t;INSERT INTO $t SELECT * FROM saved_$t;`n"}
 $setup+="UPDATE gameobject_template SET AIName='SmartGameObjectAI',ScriptName=IF(entry=248572,'go_artifact_acquisition','') WHERE entry IN(248572,248574);DELETE FROM smart_scripts WHERE entryorguid IN(248572,248574) AND source_type=1;DELETE FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry IN(248572,248574);DELETE FROM spell_script_names WHERE (spell_id=208011 AND ScriptName IN('spell_lights_wrath_pickup_cast','spell_lights_wrath_pickup_scene')) OR(spell_id=218172 AND ScriptName='spell_lights_wrath_return');"
 function InsertRows($table,$fields,$rows){$values=@();foreach($row in $rows){$cell=@();foreach($field in $fields){$value=$row.$field;if($value -is [string]){$cell+="'"+$value.Replace("'","''")+"'"}elseif($null -eq $value){$cell+='NULL'}else{$cell+=[Convert]::ToString($value,[Globalization.CultureInfo]::InvariantCulture)}};$values+='('+($cell -join ',')+')'};'INSERT INTO '+$table+'('+($fields -join ',')+') VALUES'+($values -join ',')+';'}
 $restore=(InsertRows smart_scripts $native.fields $native.rows)+(InsertRows conditions $native.conditions_fields $native.conditions_rows)
 $setup+=$restore
 # Migration07 later retires the shared Mage producer. Reconstruct its pinned
 # historical row only in TEMP so06's original guard remains reproducible.
 $setup+="DELETE FROM smart_scripts WHERE entryorguid=106756 AND source_type=0 AND id=4;"+(InsertRows smart_scripts $native.fields $native.shared_rows)
 function Snapshot([string]$label,[switch]$Filtered){($filters.Keys|ForEach-Object {$where=if($Filtered){' WHERE '+$filters[$_]}else{''};"SELECT '$label-$_',a.* FROM $_ a$where;"}) -join "`n"}
 function Signature($rows,[string]$label){(@($rows|Where-Object {$_ -like "$label`t*"}|ForEach-Object {$_.Substring($label.Length+1)}|Sort-Object -CaseSensitive)) -join "`n"}
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 function Query([string]$sql,[switch]$Expected){$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$db[3];$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names --force 2> "$out/sql-stderr.txt");$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior};$err=Get-Content "$out/sql-stderr.txt" -Raw;if($Expected){if($err -notmatch '1644 \(45000\)' -or @($err -split "`n"|Where-Object {$_ -match '^ERROR '}).Count -ne 1){throw 'Expected pickup refusal missing'}}elseif($code -or $err){throw 'Pickup TEMP/read-only query failed'};$rows}
 # Normalize precisely the intended changes to compare every retained column.
 $normalize="UPDATE gameobject_template SET AIName='SmartGameObjectAI',ScriptName=IF(entry=248572,'go_artifact_acquisition','') WHERE entry IN(248572,248574);DELETE FROM spell_script_names WHERE (spell_id=208011 AND ScriptName IN('spell_lights_wrath_pickup_cast','spell_lights_wrath_pickup_scene')) OR(spell_id=218172 AND ScriptName='spell_lights_wrath_return');"+(InsertRows smart_scripts $native.fields @($native.rows|Where-Object {$_.entryorguid -eq 248572}))+(InsertRows conditions $native.conditions_fields $native.conditions_rows)
 $rows=Query "$setup`n$(Snapshot 'original')`n$migration`n$(Snapshot 'first')`n$migration`n$(Snapshot 'second')`nSELECT 'bindings',COUNT(*) FROM spell_script_names WHERE ABS(spell_id) IN(208011,218172);SELECT 'root',COUNT(*) FROM smart_scripts WHERE entryorguid=248572 AND source_type=1;SELECT 'retired-conditions',COUNT(*) FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=248572;SELECT 'portal',COUNT(*) FROM smart_scripts WHERE entryorguid=248574 AND source_type=1;`n$normalize`n$(Snapshot 'normalized')"
 foreach($t in $filters.Keys){if((Signature $rows "first-$t") -cne (Signature $rows "second-$t")){throw 'Pickup migration not idempotent'};if((Signature $rows "original-$t") -cne (Signature $rows "normalized-$t")){throw "Pickup changed another row/field: $t"}}
 foreach($e in @("bindings`t3","root`t0","retired-conditions`t0","portal`t1")){if($rows -notcontains $e){throw 'Pickup replacement count differs'}}
 $changes=@("UPDATE gameobject_template SET ScriptName='custom' WHERE entry=248572;","UPDATE gameobject_template SET AIName='' WHERE entry=248574;",'UPDATE gameobject_template SET Data1=0 WHERE entry=248572;','UPDATE gameobject_template SET Data0=1 WHERE entry=248574;','DELETE FROM smart_scripts WHERE entryorguid=248572 AND source_type=1 AND id=1;','UPDATE smart_scripts SET link=0 WHERE entryorguid=248572 AND source_type=1 AND id=0;','UPDATE smart_scripts SET event_flags=0 WHERE entryorguid=248574 AND source_type=1;','UPDATE smart_scripts SET target_o=0 WHERE entryorguid=106756 AND source_type=0 AND id=4;','DELETE FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=248572 AND ElseGroup=0;',"INSERT INTO spell_script_names VALUES(208011,'custom');",'UPDATE spell_scene SET PlaybackFlags=0 WHERE MiscValue=1244;','UPDATE spell_target_position SET target_map=1 WHERE id=218172;',"INSERT INTO smart_scripts(entryorguid,source_type,id,event_type,action_type,action_param1,comment) VALUES(999999,0,0,61,50,248574,'custom producer');")
 foreach($change in $changes){$r=Query "$setup`n$change`n$(Snapshot 'before')`n$migration`n$(Snapshot 'after')" -Expected;foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw "Refused pickup changed $t"}}}
 if($VerifyLive){
  $sha=[Security.Cryptography.SHA1]::Create();try{$hash=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(([IO.File]::ReadAllText((Resolve-Path $MigrationPath))).Replace("`r`n","`n")))).Replace('-','')}finally{$sha.Dispose()}
  $live=Query "SET SESSION TRANSACTION READ ONLY;SELECT 'update',hash,state FROM updates WHERE name='2026_10_27_06_lights_wrath_pickup_recovery.sql';SELECT 'aluneth-superseded',COUNT(*) FROM updates WHERE name='2026_10_27_07_aluneth_pickup_recovery.sql' AND state='RELEASED';$(Snapshot 'live' -Filtered)"
  if($live -notcontains "update`t$hash`tRELEASED"){throw 'Live pickup updater/hash differs'}
  foreach($t in $filters.Keys){
   $expected=Signature $rows "first-$t";$actual=Signature $live "live-$t"
   if($t -eq 'smart_scripts' -and $live -contains "aluneth-superseded`t1"){
    $expected=(@($expected -split "`n"|Where-Object {$_ -notmatch '^106756\t0\t4\t'})) -join "`n"
    if($actual -match '(?m)^106756\t0\t4\t'){throw 'Released Aluneth migration still has retired portal producer'}
   }
   if($expected -cne $actual){[IO.File]::WriteAllText("$out/live-difference-$t.txt", "EXPECTED`n"+$expected+"`nACTUAL`n"+$actual);throw "Live pickup differs: $t"}
  }
 }
 'PASS seven complete TEMP tables, repeated migration, exact normalization and thirteen custom refusals; historical06 Mage producer/portal SAI unchanged in TEMP, later released07 producer retirement checked on live; other218172 templates, scene1600/1244 and native target/source4/source17 rules. No character mutation.'
}
